    printSTS(apiSts);
    apiSts = XmlBeans.compileXmlBeans(null, null, null, null, XmlBeans.getBuiltinTypeSystem(), null, null);
    printSTS(apiSts);
    boolean iArgExThrown = false;
    try {
        apiSts = XmlBeans.compileXmlBeans(null, null, null, null, null, null, null);
        printSTS(apiSts);
    } catch (IllegalArgumentException iaEx) {
        iArgExThrown = true;
