    assertTrue(nonnegIntDoc.validate(validateOptions));
    UnsignedLongEltDocument uLongDoc = UnsignedLongEltDocument.Factory.parse("<UnsignedLongElt " + " xmlns=\"http://xbean/scomp/contentType/builtIn/Number\"" + ">18446744073709551615</UnsignedLongElt>");
