    // load schema file as SchemaDocument XmlObject
    SchemaDocument sd = SchemaDocument.Factory.parse(xsdAsString.toString());
    // compile loaded XmlObject
    try {
        XmlOptions options = new XmlOptions();
        List errors = new ArrayList();
        options.setErrorListener(errors);
        SchemaTypeSystem sts = XmlBeans.compileXsd((XmlObject[]) Collections.singletonList(sd).toArray(new XmlObject[] {}), XmlBeans.getContextTypeLoader(), options);
