    assertTrue(!doc.validate(validateOptions));
    showErrors();
    String[] errExpected = new String[] { XmlErrorCodes.DATATYPE_LENGTH_VALID$LIST_LENGTH };
    assertTrue(compareErrorCodes(errExpected));
