 * TODO: verify that w/ respect to substitution
 * groups block all
 * and block substitution are the same thing;
 *
 * @throws Throwable
 */
@Test
public void testBlockAllInvalid() throws Throwable {
    //should not be able to use CasualBusinessShirt  instead of shirt
    //but BusinessShirt instead of shirt should be OK
    String input = "<base:items xmlns:pre=\"http://xbean/scomp/substGroup/Block\"" + " xmlns:base=\"http://xbean/scomp/substGroup/Deep\">" + "<pre:casualBShirt>" + " <number>SKU25</number>" + " <name>Oxford Shirt</name>" + " <size>12</size>" + " <color>blue</color>" + "<pokadotColor>yellow</pokadotColor>" + "</pre:casualBShirt>" + "<base:product>" + " <number>SKU45</number>" + "   <name>Accessory</name>" + "</base:product>" + "<pre:umbrella>" + " <number>SKU15</number>" + "   <name>Umbrella</name>" + "</pre:umbrella>" + "<pre:casualBShirt>" + " <number>SKU25</number>" + " <name>Oxford Shirt</name>" + " <size>12</size>" + " <color>blue</color>" + "<pokadotColor>yellow</pokadotColor>" + "</pre:casualBShirt>" + "</base:items>";
    ItemsDocument doc = ItemsDocument.Factory.parse(input);
    assertTrue(!doc.validate(validateOptions));
    showErrors();
    String[] errExpected = new String[] { XmlErrorCodes.ELEM_COMPLEX_TYPE_LOCALLY_VALID$ELEMENT_NOT_ALLOWED };
    assertTrue(compareErrorCodes(errExpected));
    ShirtType bs = BusinessShirtType.Factory.newInstance();
    bs.setName("Bus Shirt");
    bs.setNumber("SKU35");
    bs.setColor("blue");
    bs.setSize(new BigInteger("10"));
    doc.getItems().setProductArray(new ProductType[] { bs });
    XmlCursor cur = doc.newCursor();
    cur.toFirstContentToken();
    cur.toNextToken();
    cur.toNextToken();
    cur.toNextToken();
    assertEquals(XmlCursor.TokenType.START, cur.currentTokenType());
    cur.setName(new QName("http://xbean/scomp/substGroup/Block", "businessShirt", "pre"));
    System.out.println("*************** " + doc.xmlText());
    try {
        assertTrue(doc.validate(validateOptions));
    } catch (Throwable t) {
        showErrors();
        throw t;
    }
}

