@Test
public void testCopyDifferentStoresLoadedFromFile() throws Exception {
    // load the documents and obtain a cursor
    XmlObject xobj0 = XmlObject.Factory.parse(JarUtil.getResourceFromJar(Common.TRANXML_FILE_CLM));
    XmlObject xobj1 = XmlObject.Factory.parse(JarUtil.getResourceFromJar("xbean/xmlcursor/po.xml"));
