    // should contain all the namespaces for the document
    assertEquals("<Initial xmlns=\"" + Common.CLM_NS + "\" " + Common.CLM_XSI_NS + ">GATX</Initial>", xc0.xmlText());
    xc0.dispose();
    xc1.dispose();
}

