    //
    x = XmlObject.Factory.parse("<foo>a&lt;b&amp;c</foo>");
    assertEquals("<foo>a&lt;b&amp;c</foo>", x.xmlText());
    //
    x = XmlObject.Factory.parse("<foo></foo>");
