    String sOExpectedXML = "<xml-fragment " + sNamespace + ">" + "<loc:CityName>DALLAS</loc:CityName>" + "<loc:StateCode>TX</loc:StateCode>" + "<loc:SubdivisionCode>xyz</loc:SubdivisionCode>" + "</xml-fragment>";
