@Test
public void testCR196679() throws Exception {
    TestDocument testDoc = null;
    String input = "<ns:test xmlns:ns=\"http://xbean.test/xmlcursor/CR196679\">\n" + "  <ns:name>myTest</ns:name>" + "  <ns:value>5</ns:value>" + "  </ns:test>";
    testDoc = TestDocument.Factory.parse(input);
    TestType test = testDoc.getTest();
    String queryName = "declare namespace ns='http://xbean.test/xmlcursor/CR196679'" + "$this/ns:name";
    String queryValue = "declare namespace ns='http://xbean.test/xmlcursor/CR196679'" + "$this/ns:value";
    XmlCursor cursor = test.newCursor();
    cursor.push();
    cursor.selectPath(queryName);
    cursor.toNextSelection();
    assertEquals("myTest", cursor.getTextValue());
    cursor.pop();
    cursor.selectPath(queryValue);
    cursor.toNextSelection();
    //expected output is value=5
    assertEquals("5", cursor.getTextValue());
    cursor.dispose();
}

