@Test
public void testSaverCharEscaping() throws XmlException {
    XmlObject xdoc = XmlObject.Factory.parse("<test>something</test>");
    XmlCursor cur = xdoc.newCursor();
    cur.toFirstChild();
    // valid chars
    cur.setTextValue("<something or other:\u03C0\uD7FF>");
