@Test
public void testWorld1() throws Exception {
    NameworldDocument doc = (NameworldDocument) XmlObject.Factory.parse(JarUtil.getResourceFromJarasFile("xbean/xmlobject/nameworld.xml"));
    assertEquals(new QName("http://openuri.org/nameworld", "nameworld"), doc.schemaType().getDocumentElementName());
    QName[] contents = { new QName("http://bar.com/", "barcity"), new QName("http://foo.com/", "footown"), new QName("http://bar.com/", "barvillage"), new QName("http://bar.com/", "bartown"), new QName("http://foo.com/", "foovillage"), new QName("http://bar.com/", "barvillage"), new QName("http://foo.com/", "foocity"), new QName("http://bar.com/", "bartown"), new QName("http://foo.com/", "foovillage"), new QName("http://foo.com/", "footown"), new QName("http://bar.com/", "barvillage"), new QName("http://foo.com/", "foovillage") };
    int t = 0;
    Nameworld world = doc.getNameworld();
    Nameworld.Island[] islands = world.getIslandArray();
    for (int i = 0; i < islands.length; i++) {
        Loc[] locs = islands[i].getLocationArray();
        for (int j = 0; j < locs.length; j++) {
            Loc.Reference[] refs = locs[j].getReferenceArray();
            for (int k = 0; k < refs.length; k++) {
                assertEquals(contents[t++], refs[k].getTo());
            }
        }
    }
}

@Test
public void testRedefine() throws XmlException {
    String xml = "<newSize xmlns='http://example.org/prod'>7</newSize>";
    NewSizeDocument nsDoc = NewSizeDocument.Factory.parse(xml);
    boolean valid = nsDoc.validate();
    assertTrue(valid);
    assertEquals(7, nsDoc.getNewSize());
    nsDoc.setNewSize(20);
    List errors = new ArrayList();
    XmlOptions options = new XmlOptions();
    options.setErrorListener(errors);
    valid = nsDoc.validate(options);
    assertFalse(valid);
    assertEquals(1, errors.size());
}

