/**
 * Simple Compilation Tests - If the methods are not present,
 * - this class won't compile
 * Ensures method getSourceName is on SchemaComponent and
 * can be called from SchemaGlobalElement and SchemaGlobalAttribute
 */
@Test
public void test199585() throws Exception {
    String str = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n" + "<xs:schema xmlns:xs=\"http://www.w3.org/2001/XMLSchema\"\n" + "    targetNamespace=\"urn:lax.Doc.Compilation\"\n" + "    xmlns:tns=\"urn:lax.Doc.Compilation\"\n" + "    xmlns:pre=\"noResolutionNamespace\"\n" + "    elementFormDefault=\"qualified\"\n" + "    attributeFormDefault=\"unqualified\">\n" + "   <xs:element name=\"QuantityElement\" type=\"tns:quantity\" />" + "   <xs:simpleType name=\"quantity\">\n" + "    <xs:restriction base=\"xs:NMTOKEN\">\n" + "      <xs:enumeration value=\"all\"/>\n" + "      <xs:enumeration value=\"most\"/>\n" + "      <xs:enumeration value=\"some\"/>\n" + "      <xs:enumeration value=\"few\"/>\n" + "      <xs:enumeration value=\"none\"/>\n" + "    </xs:restriction>\n" + "  </xs:simpleType>" + "</xs:schema>";
    XmlObject[] schemas = new XmlObject[] { XmlObject.Factory.parse(str) };
    XmlOptions xOpt = new XmlOptions().setValidateTreatLaxAsSkip();
    SchemaTypeSystem sts = XmlBeans.compileXmlBeans(null, null, schemas, null, XmlBeans.getBuiltinTypeSystem(), null, xOpt);
    //ensure SchemaGlobalElement has getSourceName Method
    SchemaGlobalElement[] sge = sts.globalElements();
    for (int i = 0; i < sge.length; i++) {
        System.out.println("SGE SourceName: " + sge[i].getSourceName());
    }
    //ensure SchemaGlobalAttribute has getSourceName Method
    SchemaGlobalAttribute[] sga = sts.globalAttributes();
    for (int i = 0; i < sga.length; i++) {
        System.out.println("SGE SourceName: " + sga[i].getSourceName());
    }
    //ensure SchemaGlobalElement is a subType of SchemaComponent
    SchemaComponent[] sce = sts.globalElements();
    for (int i = 0; i < sce.length; i++) {
        System.out.println("SCE SourceName: " + sce[i].getSourceName());
    }
    //ensure SchemaGlobalAttribute is a subType of SchemaComponent
    SchemaComponent[] sca = sts.globalElements();
    for (int i = 0; i < sca.length; i++) {
        System.out.println("SCA SourceName: " + sca[i].getSourceName());
    }
}

/**
 * Tests read-only concurrency support in XML Beans
 * See Radar Bug: 33254
 */
@Test
public void testConcurrency() throws Exception {
    // Get the file contents
    String xmlFile = JarUtil.getResourceFromJar("xbean/xmlcursor/po.xml");
    StringXmlReader rdr1 = new StringXmlReader(xmlFile);
    StringXmlReader rdr2 = new StringXmlReader(xmlFile);
    StringXmlReader rdr3 = new StringXmlReader(xmlFile);
    Thread t1 = new Thread(rdr1, "Reader1");
    Thread t2 = new Thread(rdr2, "Reader2");
    Thread t3 = new Thread(rdr3, "Reader3");
    t1.start();
    t2.start();
    t3.start();
    // Wait for threads to finish
    t1.join();
    t2.join();
    t3.join();
    // Check the status of the XmlReaders
    boolean status = rdr1.getStatus() & rdr2.getStatus() & rdr3.getStatus();
    assertTrue("Concurrency Test Failed.", status);
}

